const Joi = require('joi');
const { AI_RUN_STATUS, AI_LIMITS } = require('../constants');

/** Match the UUID v4 identifiers generated by the current database schema. */
const uuid = () => Joi.string().uuid({ version: 'uuidv4' });
const seasonParams = Joi.object({ seasonId: uuid().required() });

const create = {
    params: seasonParams,
    query: Joi.object({}),
    body: Joi.object({}).default({}),
};

// Check route identity before admission or multipart parsing; files are validated by middleware.
const createParams = {
    params: seasonParams,
    query: Joi.object({}),
};

const list = {
    params: seasonParams,
    query: Joi.object({
        limit: Joi.number()
            .integer()
            .min(1)
            .max(AI_LIMITS.MAX_PAGE_SIZE)
            .default(AI_LIMITS.DEFAULT_PAGE_SIZE),
        cursor: Joi.string().base64({ urlSafe: true, paddingRequired: false }).max(512),
        runStatus: Joi.string().valid(...Object.values(AI_RUN_STATUS)),
    }),
};

const detail = {
    params: Joi.object({ seasonId: uuid().required(), diagnosisId: uuid().required() }),
    query: Joi.object({}),
};

module.exports = {
    create,
    createParams,
    list,
    detail,
};
